import { randomBytes } from 'node:crypto';

const ALPHABET = '0123456789abcdefghijkmnopqrstuvwxyz';

/** Random URL-safe id with a short prefix, e.g. ses_7k2m9x… */
export function newId(prefix = '', bytes = 12) {
  const buf = randomBytes(bytes);
  let out = '';
  for (const b of buf) out += ALPHABET[b % ALPHABET.length];
  return prefix ? `${prefix}_${out}` : out;
}

export function token(bytes = 32) {
  return randomBytes(bytes).toString('base64url');
}

/** Ids generated by newId are restricted to [a-z0-9_]; anything else is rejected before touching the filesystem. */
export function isSafeId(id) {
  return typeof id === 'string' && /^[a-z0-9_]{3,64}$/.test(id);
}
